return ['domain'=>NULL,'plural-forms'=>'nplurals=4; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<12 || n%100>14) ? 1 : n%10==0 || (n%10>=5 && n%10<=9) || (n%100>=11 && n%100<=14)? 2 : 3);','language'=>'be','project-id-version'=>'WPGlobus Multilingual','pot-creation-date'=>'2026-02-01 02:55+0000','po-revision-date'=>'2015-09-03 17:28+0000','messages'=>['Guide'=>'Инструкция','WPGlobus Help Desk'=>'Поддержка','Add-ons'=>'Расширения','Quick Start'=>'Быстрый Старт','FAQ'=>'ЧаВо','Attention: the Multibyte String PHP extension (`mbstring`) is not loaded!'=>'Внимание: расширение PHP Multibyte String (`mbstring`) не загружено!','The mbstring extension is required for the full UTF-8 compatibility and better performance. Without it, some parts of WordPress and WPGlobus may function incorrectly. Please contact your hosting company or systems administrator.'=>'Расширение mbstring необходимо для поддержки UTF-8 и для улучшенной производительности. Без этого расширения некоторые части ВордПресс и WPGlobus могут функционировать некорректно. Пожалуйста, сообщите вашему провайдеру или системному администратору (вебмастеру).','Go to WPGlobus Settings'=>'Перейдите в настройки WPGlobus','Easy as 1-2-3:'=>'Просто, как 1-2-3:','Go to WPGlobus admin menu and choose the countries / languages;'=>'Войдите в меню администратора WPGlobus и выберите страны и языки;','Enter the translations to the posts, pages, categories, tags and menus using a clean and simple interface.'=>'Введите переводы записей, страниц, категорий, меток и меню, используя простой и удобный интерфейс.','Switch languages at the front-end using a drop-down menu with language names and country flags.'=>'Переключайте языки, используя раскрывающееся меню с их названиями и флагами стран.','Links:'=>'Ссылки:','FAQs'=>'Вопросы и ответы','Contact Us'=>'Обратная связь','Please give us 5 stars!'=>'Пожалуйста, поставьте нам 5 звездочек!','WPGlobus does not translate texts automatically!'=>'WPGlobus не делает автоматические переводы текста!','There are many translation companies and individual translators who can help you write and proofread the texts.'=>'Вы можете воспользоваться услугами профессиональных переводчиков.','When you choose a translator, please look at their native language, country of residence, specialization and knowledge of WordPress.'=>'При выборе переводчика обратите внимание на родной язык, страну проживания, специализацию и знание ВордПресс.','Important notes:'=>'Важная информация:','WPGlobus only supports the localization URLs in the form of <code>example.com/xx/page/</code>. We do not plan to support subdomains <code>xx.example.com</code> and language queries <code>example.com?lang=xx</code>.'=>'WPGlobus поддерживает только локализацию URL-адреса в виде <code>example.com/xx/page/</code>. Мы не планируем поддерживать дочерние домены <code>xx.example.com</code> и языковые параметры в УРЛах <code>example.com?lang=xx</code>.','Some themes and plugins are <strong>not multilingual-ready</strong>.'=>'Некоторые темы и плагины <strong>не полностью поддерживают многоязычный режим</strong>.','They might display some texts with no translation, or with all languages mixed together.'=>'Они могут выводить на экран некоторые тексты без перевода, или смешивая разные языки.','Please contact the theme / plugin author. If they are unable to assist, consider %1$s hiring the WPGlobus Team %2$s to write a custom code for you.'=>'Пожалуйста, свяжитесь с авторами темы / плагина. Если они не могут помочь, рассмотрите возможность %1$s дать заказ команде разработчиков WPGlobus %2$s на написание кода специально для Вас.','Add'=>'Добавить','WPGlobus is a family of WordPress plugins assisting you in making multilingual WordPress blogs and sites.'=>'WPGlobus - это коллекция плагинов ВордПресс для создания многоязычных сайтов.','Remove the WPGlobus settings (not recommended)'=>'Удалить настройки WPGlobus (не рекомендуется)','Clean-up Tool'=>'Программа очистки','WARNING: this operation is non-reversible. It is strongly recommended that you backup your database before proceeding.'=>'Предупреждение: эта операция является необратимой. Настоятельно рекомендуем сделать резервную копию базы данных перед продолжением.','This tool should be used only if you plan to completely uninstall WPGlobus. By running it, you will remove ALL translations you have entered to your post, pages, etc., keeping only the MAIN language texts. Please make sure that all entries have some content in the main language. Otherwise, you might end up with empty titles, no content, no excerpts, blank comments and so on.'=>'Эту программу следует использовать только, если Вы планируете полностью удалить WPGlobus. Программа удалит все переводы в записях, страницах, и т.п., сохраняя только тексты на основном языке. Пожалуйста, убедитесь, что во всех записях присутствует контент на основном языке. В противном случае Вы обнаружите пустые заголовки, отсутствие контента страниц, пустые комментарии и тому подобное.','You are about to clean the content of the following database tables:'=>'Программа выполнит очистку следующих таблиц базы данных:','The operations log'=>'Журнал операций','We are going to write a detailed log of all the database changes performed. It should help in the case you need to restore something important. The log will be written to the file:'=>'Мы собираемся записать все изменения в базе данных в журнал. Он может помочь в случае, если Вам потребуется восстановить что-то важное. Журнал будет записываться в файл:','Uncheck if you do not want to write the operations log (we recommend to keep it checked)'=>'Снимите флажок, если Вы не хотите записывать операции в журнал (мы рекомендуем оставить запись включённой)','You have been warned...'=>'Вы уверены, что готовы продолжить?','Please confirm by checking the box below:'=>'Пожалуйста, подтвердите, установив флажок ниже:','I have read and understood everything written on this page. I am aware that by using this tool I may loose some content of my website. I have made a database backup and know how to restore it if necessary. I am fully responsible for the results.'=>'Мне понятно всё, что написано на этой странице. Я знаю, что в результате запуска Программы очистки я могу потерять некоторую часть контента моего веб-сайта. Мною выполнена резервная копия базы данных, и я знаю, как восстановить её в случае необходимости. Я полностью несу ответственность за результат.','YES, I CONFIRM'=>'ДА, Я ПОДТВЕРЖДАЮ','Process with the Clean-up'=>'Запустить программу очистки','Default'=>'По умолчанию','Section'=>'Раздел','Show all sections'=>'Показать все разделы','Save &amp; Reload'=>'Сохранить и перезагрузить','WPGlobus'=>'WPGlobus','You need to update WordPress to 4.5 or later to get Fields Settings section'=>'Этот раздел доступен в WordPress версии 4.5 и выше.','Fields Settings'=>'Настройки полей','WPGlobus Settings'=>'Настройки WPGlobus','Help'=>'Дапамога','Languages'=>'Языки','Enabled Languages'=>'Установленные языки','These languages are currently enabled on your site.'=>'Эти языки включены в настоящее время на вашем сайте.','or Add new Language %1$s here %2$s'=>'или добавьте новый язык %1$s здесь %2$s','Add Languages'=>'Добавить языки','Language Selector Mode'=>'Способ показа переключателей ','Two-letter Code with flag (en, ru, it, etc.)'=>'Двухбуквенный код (en, ru, it, и т.п.) и флаг','Full Name (English, Russian, Italian, etc.)'=>'Полное название (English, Russian, Italian, и т.п.)','Full Name with flag (English, Russian, Italian, etc.)'=>'Полное название (English, Russian, Italian, и т.п.) и флаг','Flags only'=>'Только флаги','Choose the way language name and country flag are shown in the drop-down menu'=>'Выберите способ показа названий языков и флагов в навигационном меню','Language Selector Menu'=>'Навигационное меню','Choose the navigation menu where the language selector will be shown'=>'Выберите навигационное меню, в котором будет показан переключатель языков','No menus have been created yet. Create some.'=>'Ни одного меню ещё не создано. Создайте.','"All Pages" menus Language selector'=>'Переключатель языка в меню «Все страницы»','Adds language selector to the menus that automatically list all existing pages (using `wp_list_pages`)'=>'Добавить переключатель языка в меню, которые автоматически показывают список всех страниц (с использованием `wp_list_pages`)','Custom CSS'=>'Пользовательский CSS','Here you can enter the CSS rules to adjust the language selector menu for your theme. Look at the examples in the `style-samples.css` file.'=>'Сюда Вы можете поместить набор правил CSS для тонкой настройки меню выбора языков. Примеры для стандартных тем можно найти в файле `style-samples.css`.','Post types'=>'Типы записей','Uncheck to disable WPGlobus'=>'Снимите флажок, чтобы отключить WPGlobus','Redirect'=>'Перенаправление','Choose the language automatically, based on:'=>'Выбрать язык автоматически, учитывая:','Preferred language set in the browser'=>'Язык, указанный как предпочтительный в настройках браузера','When a user comes to the site for the first time, try to find the best matching language version of the page.'=>'Когда посетитель попадает на сайт в первый раз, попытаться выбрать язык страницы автоматически.','Custom JS Code'=>'Пользовательский JS','Title'=>'Заголовок','(Paste your JS code here.)'=>'(Поместите сюда JS код.)','Label'=>'Метка','Description'=>'Описание','Here you can specify which fields should be considered multilingual by WPGlobus. To exclude a field, uncheck it and then press the button %s below.'=>'Здесь Вы можете указать, какие поля считаются многоязычными и должны обрабатываться WPGlobus. Чтобы исключить поле, снимите отметку и нажмите кнопку %s внизу.','Thank you for installing WPGlobus!'=>'Спасибо за то, что Вы установили плагин WPGlobus!','Read About WPGlobus'=>'Подробно о WPGlobus','Click the <strong>[Languages]</strong> tab at the left to setup the options.'=>'Настройки плагина находятся в разделе <strong>[Языки]</strong>.','Should you have any questions or comments, please do not hesitate to contact us.'=>'Если у Вас есть вопросы или замечания, пожалуйста, обращайтесь к нам за поддержкой.','Sincerely Yours,'=>'С Уважением,','The WPGlobus Team'=>'Команда WPGlobus','We would hate to see you go. If something goes wrong, do not uninstall WPGlobus yet. Please %1$stalk to us%2$s and let us help!'=>'Обнаружили проблему в WPGlobus? Не торопитесь удалять плагин. Пожалуйста %1$sобратитесь к нам%2$s и позвольте Вам помочь!','Please note that if you deactivate WPGlobus, your site will show all the languages together, mixed up. You will need to remove all translations, keeping only one language.'=>'Пожалуйста, обратите внимание: если Вы отключите WPGlobus, Ваш сайт будет показывать все языки одновременно. Вам будет необходимо удалить все переводы, сохранив только один язык.','If there are just a few places, you should edit them manually. To automatically remove all translations at once, you can use the %s. WARNING: The clean-up operation is irreversible, so use it only if you need to completely uninstall WPGlobus.'=>'Если есть лишь несколько мест с переводами, стоит отредактировать их вручную. Чтобы автоматически удалить все переводы сразу, можно использовать %s. Предупреждение: операция очистки является необратимой, так что используйте её, только если Вы решили окончательно удалить WPGlobus.','%1$sClean-up Tool%2$s'=>'%1$sПрограмму очистки%2$s','Sorry, WPGlobus customizer doesn\'t support current theme %s.'=>'Извините, тема %s не поддерживается WPGlobus.','Please use %1$sWPGlobus options page%2$s instead.'=>'Пожалуйста, используйте %1$sпанель настроек WPGlobus%2$s.','WPGlobus News'=>'Новости WPGlobus','Options updated'=>'Настройки сохранены','Please enter a language code!'=>'Пожалуйста, введите код языка!','Language code already exists!'=>'Такой код языка уже существует!','Please specify the language flag!'=>'Пожалуйста, укажите флаг для языка!','Please enter the language name!'=>'Пожалуйста, введите название языка!','Please enter the language name in English!'=>'Пожалуйста, введите название языка по-английски!','Please enter the locale!'=>'Пожалуйста, введите локаль!','Add Language'=>'Добавить язык','Delete Language'=>'Удалить язык','Edit Language'=>'Изменить язык','Language Code'=>'Код языка','2-Letter ISO Language Code for the Language you want to insert. (Example: en)'=>'Двухбуквенная ISO-кодировка языка, который Вы хотите добавить (Пример: en)','Language flag'=>'Флаг','Name'=>'Название','The name of the language in its native alphabet. (Examples: English, Русский)'=>'Название на языке оригинала. (Пример: English, Русский)','Name in English'=>'Название по-английски','The name of the language in English'=>'Название языка по-английски','Locale'=>'Локаль','PHP/WordPress Locale of the language. (Examples: en_US, ru_RU)'=>'PHP/WordPress локаль языка. (Пример: en_US, ru_RU)','Are you sure you want to delete?'=>'Удалить? Вы уверены?','Save Changes'=>'Сохранить изменения','Back to the WPGlobus Settings'=>'Вернуться к настройкам WPGlobus','Current Version'=>'Текущая версия','Premium add-on'=>'Платное расширение','Installed'=>'Установлен','Get it now!'=>'Установить!','Help Desk'=>'Поддержка','Thank you for using WPGlobus!'=>'Спасибо за то, что Вы выбрали WPGlobus!','Our Support Team is here to answer your questions or concerns.'=>'Наша Служба Поддержки постарается ответить на любой из Ваших вопросов.','To help us serve you better:'=>'Чтобы ускорить поиск решения Вашей проблемы:','Please check if the problem persists if you switch to a standard WordPress theme.'=>'Пожалуйста, убедитесь, что проблема сохраняется, если Вы переключитесь на стандартную тему ВордПресс.','Try deactivating other plugins to see if any of them conflicts with WPGlobus.'=>'Попробуйте деактивировать плагины, чтобы убедиться, не конфликтует ли какой-то из них с WPGlobus.','Technical Information'=>'Техническая информация','WPGlobus Recommends:'=>'WPGlobus рекомендует:','WPGlobus for WooCommerce'=>'WPGlobus для WooCommerce','Translate product titles and descriptions, product categories, tags and attributes.'=>'Переведите названия и описания товаров, категорий, свойств и меток.','Get it now:'=>'Установите прямо сейчас:','Accept multiple currencies in your online store!'=>'Принимайте оплату в нескольких валютах!','Check it out:'=>'Информация - здесь:','WPGlobus widget'=>'WPGlobus виджет','Add language switcher'=>'Добавить переключатель языка','Flags'=>'Флаги','List'=>'Список','List with flags'=>'Список с флажками','Select'=>'Select','Select with language code'=>'Select с кодом языка','Dropdown'=>'Выпадающее меню','Dropdown with flags'=>'Выпадающее меню с флагами','Selector type'=>'Способ выбора языка','You cannot disable the main language.'=>'Нельзя отключить основной язык.','*) Available after the menu is saved.'=>'*) Доступно после сохранения меню.','You must enable Pretty Permalinks to use WPGlobus.'=>'Чтобы использовать плагин WPGlobus, необходимо включить ЧПУ - постоянные ссылки.','Please go to Settings > Permalinks > Common Settings and choose a non-default option.'=>'Пожалуйста, перейдите в меню Настройки > Постоянные ссылки и поменяйте структуру ссылок в разделе "Общие настройки".','Welcome!'=>'Добро пожаловать!','Deactivating / Uninstalling'=>'Деактивация / Деинсталляция','Select a language'=>'Выберите язык','When done, click the [Save Changes] button.'=>'Когда закончите, нажмите кнопку [Сохранить изменения].','Instructions:'=>'Инструкции:','(Found in some themes)'=>'(Используется в некоторых темах)','Enable'=>'Включить','Languages table'=>'Таблица языков','Use this table to add, edit or delete languages.'=>'Используйте эту таблицу, чтобы добавлять, удалять или редактировать языки.','NOTE: you cannot remove the main language.'=>'ВНИМАНИЕ: язык по умолчанию не может быть удален.','item'=>'запись','items'=>'записей','Code'=>'Код','Edit'=>'Изменить','Delete'=>'Удалить','File'=>'Файл','Flag'=>'Флаг','Language name'=>'Название языка','English language name'=>'Название языка по-английски','No items found'=>'Нет записей','Add new Language'=>'Добавить новый язык','No items of this type were found.'=>'Нічога не знойдзена.','Status'=>'Статус','Active'=>'Активировано','We rely on your support!'=>'Спасибо за поддержку!','Please consider a small donation to support the future development.'=>'Ваше пожертвование будет использовано для дальшейшего развития и улучшения плагина.','Thank you!'=>'С благодарностью!','WPGlobus Plus!'=>'WPGlobus Плюс!','Advanced features and tweaks: URL translation, multilingual SEO analysis, separate publishing and more! '=>'Расширенные функции и настройки: переводы УРЛов, многоязычный SEO анализ, раздельная публикация и многое другое! ','Get WPGlobus Plus now!'=>'Установите WPGlobus Плюс прямо сейчас!','A WordPress Globalization / Multilingual Plugin. Posts, pages, menus, widgets and even custom fields - in multiple languages!'=>'Многоязычные сайты на ВордПресс. Редактируйте тексты записей, страниц, меню, виджетов, и т.п. - на нескольких языках сразу!']];